// Heurística de Nielsen 2: 50 problemas aprofundados pela UBERTRIZ
window.PROBLEMAS.push(
{"id":51,"h":2,"sev":3,"t":"Rótulos com termos internos","sym":"O app da casa inteligente chama cômodos de “Zonas” e aparelhos de “Endpoints”.","ten":"A equipe pensa na estrutura do banco de dados; quem usa pensa nas próprias tarefas.","sol":"Triangular vocabulários: card sorting com moradores e rótulos no vocabulário deles (“Cômodos”, “Aparelhos”) em todo o produto.","c":"C35","u":"U03","e":"macro","i":"I03","m":"Acerto em teste de primeiro clique","freq":3,"imp":2,"pers":2,"pf":"P16","hx":["BS7","BS8","GP5","DN8","ISO3","NI6"],"dom":"casa","vul":"","ag":"Ganha: quem usa a casa conectada. Perde: a equipe perde o vocabulário técnico como padrão.","alt":"E se o problema for a equipe projetar a partir da estrutura do sistema? Então rótulos novos não bastam; o modelo precisa mudar.","esc":{"micro":"Trocar os rótulos pelos do público.","meso":"Card sorting com moradores para organizar as telas.","macro":"Triangular vocabulários: card sorting com moradores e rótulos no vocabulário deles (“Cômodos”, “Aparelhos”) em todo o produto."},"st":"mod","sub":"Remover os termos técnicos da interface; deixá-los só nas configurações avançadas.","ops":["U04","U26"],"c2":{"c":"C35","t":"O suporte técnico passa a falar uma língua diferente da interface.","mit":"Glossário comum entre suporte e interface."},"cf":"Sem intervenção, a pessoa não encontra seus aparelhos e liga para o suporte.","lim":{"l":"L07","t":"Depende de pesquisar com públicos variados."},"ide":{"mais":["I03","I07"],"menos":["I02"]},"ref":"Estaria errada se o público do produto for técnico (instaladores).","conf":"alta"},
{"id":52,"h":2,"sev":3,"t":"Ícone de significado ambíguo","sym":"No e-mail, uma engrenagem abre “Filtrar”; metade das pessoas espera “Configurações”.","ten":"O ícone deve economizar espaço, mas precisa ser entendido de imediato.","sol":"Comparar alternativas: testar o reconhecimento dos ícones candidatos com o público e manter o rótulo ao lado.","c":"C07","u":"U26","e":"micro","i":"I03","m":"Taxa de reconhecimento do ícone","freq":2,"imp":2,"pers":2,"pf":"P07","hx":["BS7","GP5","DN7","TG6","ISO2","LX4"],"dom":"comunicacao","vul":"","ag":"Ganha: quem usa o e-mail. Perde: um pouco de espaço na barra.","alt":"E se o problema for o filtro estar escondido num ícone, e não o ícone em si?","esc":{"micro":"Comparar alternativas: testar o reconhecimento dos ícones candidatos com o público e manter o rótulo ao lado.","meso":"Barra de busca com filtros visíveis em texto.","macro":"Biblioteca de ícones testada com o público."},"st":"mod","sub":"Remover o ícone e deixar só o rótulo “Filtrar”.","ops":["U01","U35"],"c2":{"c":"C16","t":"Rótulos ocupam mais espaço em telas pequenas.","mit":"Ícone + rótulo em telas grandes; menu com texto em telas pequenas."},"cf":"Sem intervenção, metade das pessoas não encontra o filtro.","lim":{"l":"L07","t":"Reconhecimento de ícones varia por cultura e idade."},"ide":{"mais":["I03"],"menos":["I02"]},"ref":"Estaria errada se o teste mostrar que o ícone é reconhecido pela maioria do público real.","conf":"média"},
{"id":53,"h":2,"sev":2,"t":"Ordem de campos que não segue a lógica local","sym":"No cadastro do app de transporte, o endereço pede rua, número, bairro, cidade… e o CEP só no fim.","ten":"O formulário segue um padrão estrangeiro; no Brasil, o CEP vem primeiro e já diz o resto.","sol":"CEP como primeiro campo, preenchendo rua, bairro e cidade automaticamente.","c":"C32","u":"U10","e":"micro","i":"I02","m":"Tempo para preencher o endereço","freq":3,"imp":1,"pers":2,"pf":"P02","hx":["BS8","BS2.2","GP1","ISO1","LX7","MB5"],"dom":"mobilidade","vul":"","ag":"Ganha: quem se cadastra. Perde: nada.","alt":"E se o endereço nem precisasse ser digitado (localização atual)?","esc":{"micro":"CEP como primeiro campo, preenchendo rua, bairro e cidade automaticamente.","meso":"Endereços salvos e sugestão pela localização.","macro":"Base de CEPs atualizada e compartilhada entre serviços."},"st":"mod","sub":"Remover os campos preenchidos pelo CEP da digitação.","ops":["U02","U13"],"c2":{"c":"C36","t":"A base de CEPs desatualizada preenche errado ruas novas.","mit":"Permitir editar o que foi preenchido."},"cf":"Sem intervenção, o preenchimento continua lento e com erros.","lim":{"l":"L03","t":"Depende de serviço de consulta de CEP."},"ide":{"mais":["I02"],"menos":[]},"ref":"Estaria errada se a maioria das pessoas não souber o próprio CEP e o autopreenchimento falhar com frequência.","conf":"alta"},
{"id":54,"h":2,"sev":3,"t":"Data e moeda no formato estrangeiro","sym":"No app de investimentos, “03/04/2026” é lido como 4 de março e “1,234.56” confunde valores.","ten":"O sistema é global, mas cada pessoa lê no padrão do seu lugar.","sol":"Formatar conforme a região: DD/MM/AAAA, R$ 1.234,56, semana começando no domingo.","c":"C29","u":"U21","e":"micro","i":"I08","m":"Erros de interpretação de datas","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["BS8","WC3.1","ISO3","GP4","MB2"],"dom":"financas","vul":"","ag":"Ganha: quem lê valores e datas. Perde: nada.","alt":"E se a pessoa usar o sistema em outro idioma de propósito?","esc":{"micro":"Formatar conforme a região: DD/MM/AAAA, R$ 1.234,56, semana começando no domingo.","meso":"Preferência de região separada do idioma.","macro":"Biblioteca de formatação regional em toda a plataforma."},"st":"mod","sub":"Remover formatações escritas à mão nas telas; usar só o formatador regional.","ops":["U12","U30"],"c2":{"c":"C29","t":"Relatórios compartilhados com outros países ficam no formato local.","mit":"Formato internacional (ISO) nos arquivos exportados."},"cf":"Sem intervenção, datas são lidas trocadas e valores com mil vezes o tamanho.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I08","I04"],"menos":[]},"ref":"Estaria errada se o público for majoritariamente estrangeiro.","conf":"alta"},
{"id":55,"h":2,"sev":4,"t":"Lixeira que apaga para sempre","sym":"Na galeria de fotos da família, o ícone é uma lixeira, mas a foto é destruída na hora, sem volta.","ten":"A metáfora promete recuperação, mas o sistema não a cumpre.","sol":"Fazer a lixeira funcionar como no mundo real: guardar por 30 dias, permitir restaurar e só então esvaziar.","c":"C03","u":"U24","e":"meso","i":"I10","m":"Pedidos de recuperação ao suporte","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG12","DN8","SH6","TG13","ISO6","BS5.3"],"dom":"casa","vul":"","ag":"Ganha: a família e suas fotos. Perde: armazenamento extra por 30 dias.","alt":"E se a exclusão precisar ser definitiva por privacidade?","esc":{"micro":"Mensagem “Movido para a lixeira — Desfazer”.","meso":"Fazer a lixeira funcionar como no mundo real: guardar por 30 dias, permitir restaurar e só então esvaziar.","macro":"Política de retenção clara e exclusão definitiva sob pedido."},"st":"add","sub":"Remover a exclusão direta; tudo passa pela lixeira.","ops":["U12","U08"],"c2":{"c":"C18","t":"Guardar itens excluídos ocupa a cota de armazenamento.","mit":"Não contar a lixeira na cota ou esvaziar automaticamente."},"cf":"Sem intervenção, fotos da família se perdem para sempre.","lim":{"l":"L04","t":"Custo de armazenamento."},"ide":{"mais":["I10"],"menos":["I11"]},"ref":"Estaria errada se as exclusões forem sempre intencionais.","conf":"alta"},
{"id":56,"h":2,"sev":2,"t":"Números crus que ninguém lê","sym":"O anexo aparece com “5242880” de tamanho e a mensagem com data “1735689600”.","ten":"O sistema armazena valores brutos, mas as pessoas pensam em unidades humanas.","sol":"Converter para “5 MB” e “há 3 minutos” (com data completa ao passar o cursor).","c":"C35","u":"U16","e":"micro","i":"I03","m":"Tempo para interpretar a informação","freq":2,"imp":1,"pers":2,"pf":"P02","hx":["GP4","GP7","BS8","DN8","WC3.1"],"dom":"comunicacao","vul":"","ag":"Ganha: quem lê. Perde: precisão para usos técnicos.","alt":"E se o número cru for necessário para alguém (técnico)?","esc":{"micro":"Converter para “5 MB” e “há 3 minutos” (com data completa ao passar o cursor).","meso":"Detalhe técnico ao passar o cursor.","macro":"Padrão de formatação humana em toda a plataforma."},"st":"mod","sub":"Remover os números crus da tela principal.","ops":["U09","U12"],"c2":{"c":"C34","t":"Arredondar esconde diferenças pequenas.","mit":"Mostrar o exato sob demanda."},"cf":"Sem intervenção, as pessoas não entendem tamanhos e datas.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I03"],"menos":["I04"]},"ref":"Estaria errada se o público for técnico e preferir o número exato.","conf":"alta"},
{"id":57,"h":2,"sev":4,"t":"Fluxo que segue o organograma","sym":"Para mudar o endereço é preciso atualizá-lo no cadastro da prefeitura e de novo no do IPTU.","ten":"A empresa é dividida em departamentos, mas a tarefa da pessoa é uma só.","sol":"Redelimitar pelo cidadão: um único cadastro de endereço que atualiza todos os serviços por trás.","c":"C11","u":"U05","e":"macro","i":"I03","m":"Dados divergentes entre setores","freq":3,"imp":2,"pers":3,"pf":"P08","hx":["BS8","ISO1","GP3","SH8","BS2.2"],"dom":"publico","vul":"","ag":"Ganha: o cidadão. Perde: os órgãos precisam integrar sistemas.","alt":"E se o problema for a falta de integração entre órgãos, e não a interface?","esc":{"micro":"Aviso: “Este endereço também será atualizado no IPTU”.","meso":"Uma tela de endereço para todos os serviços da prefeitura.","macro":"Redelimitar pelo cidadão: um único cadastro de endereço que atualiza todos os serviços por trás."},"st":"sub","sub":"A própria solução é subtrativa: elimina a atualização duplicada.","ops":["U12","U30"],"c2":{"c":"C12","t":"Um cadastro único cria dependência: um erro se espalha por todos os serviços.","mit":"Confirmar alterações e manter histórico."},"cf":"Sem intervenção, os dados ficam divergentes e as cobranças vão para o endereço antigo.","lim":{"l":"L06","t":"Integração depende de acordos entre secretarias."},"ide":{"mais":["I03","I04"],"menos":["I05"]},"ref":"Estaria errada se os serviços precisarem de endereços diferentes (residencial e de cobrança).","conf":"alta"},
{"id":58,"h":2,"sev":2,"t":"Linguagem burocrática","sym":"No portal do serviço público, o botão diz “Proceder à efetivação da solicitação”.","ten":"O texto quer soar formal, mas precisa ser entendido em um segundo.","sol":"Selecionar só o essencial: linguagem simples e verbo de ação — “Confirmar pedido”.","c":"C29","u":"U35","e":"micro","i":"I03","m":"Tempo de leitura da tela","freq":3,"imp":1,"pers":2,"pf":"P01","hx":["WC3.1","BS2.1","GP5","SH2","ISO3"],"dom":"publico","vul":"baixa escolaridade","ag":"Ganha: cidadãos de todos os níveis de escolaridade. Perde: parte da precisão jurídica sai da tela principal.","alt":"E se o texto for formal por exigência jurídica?","esc":{"micro":"Selecionar só o essencial: linguagem simples e verbo de ação — “Confirmar pedido”.","meso":"Revisar todos os textos do serviço com a linguagem simples.","macro":"Guia de linguagem simples adotado pelo órgão."},"st":"sub","sub":"A própria solução é subtrativa: corta palavras até sobrar a ação.","ops":["U04","U30"],"c2":{"c":"C23","t":"Simplificar pode perder precisão jurídica.","mit":"Texto simples na tela, texto legal no detalhe."},"cf":"Sem intervenção, quem tem baixa escolaridade depende de terceiros.","lim":{"l":"L06","t":"Normas jurídicas sobre termos."},"ide":{"mais":["I03","I06"],"menos":["I04"]},"ref":"Estaria errada se as pessoas entenderem os termos formais.","conf":"alta"},
{"id":59,"h":2,"sev":3,"t":"Controle que não imita o gesto natural","sym":"No app do ar-condicionado, a temperatura usa um botão giratório virtual difícil de arrastar com o dedo.","ten":"A imitação do objeto físico agrada, mas o mouse e o dedo não giram botões.","sol":"Controle mapeado ao movimento natural do meio: slider horizontal, direita = mais, com o valor visível.","c":"C02","u":"U16","e":"micro","i":"I01","m":"Erros de ajuste","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["DN4","DN6","TG9","LX1","WC2.5","MB3"],"dom":"casa","vul":"","ag":"Ganha: quem ajusta a casa pelo celular. Perde: parte da identidade visual “física”.","alt":"E se o controle físico existir e o app for dispensável?","esc":{"micro":"Controle mapeado ao movimento natural do meio: slider horizontal, direita = mais, com o valor visível.","meso":"Tela de clima com botões + e − e valor atual.","macro":"Controle pelo próprio aparelho e por voz."},"st":"mod","sub":"Remover o botão giratório e usar um controle linear.","ops":["U04","U22"],"c2":{"c":"C17","t":"Controles maiores ocupam a tela.","mit":"Controle compacto com ampliação ao tocar."},"cf":"Sem intervenção, as pessoas erram a temperatura.","lim":{"l":"L07","t":"Coordenação motora fina."},"ide":{"mais":["I01"],"menos":["I03"]},"ref":"Estaria errada se as pessoas preferirem o botão giratório em teste.","conf":"média"},
{"id":60,"h":2,"sev":1,"t":"Opções em ordem alfabética sem sentido","sym":"Os tamanhos aparecem como “G, GG, M, P, PP”.","ten":"A ordenação automática é fácil de programar, mas o mundo tem uma ordem própria.","sol":"Seguir a ordem natural do domínio: PP, P, M, G, GG; meses de janeiro a dezembro.","c":"C35","u":"U11","e":"micro","i":"I03","m":"Tempo de escolha da opção","freq":2,"imp":1,"pers":1,"pf":"P01","hx":["DN4","BS8","GP6","LX2"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada relevante.","alt":"E se o problema for oferecer tamanhos demais, que tornam qualquer ordem difícil de percorrer?","esc":{"micro":"Seguir a ordem natural do domínio: PP, P, M, G, GG; meses de janeiro a dezembro.","meso":"Seletor de tamanho com indicação de disponibilidade e do tamanho comprado da última vez.","macro":"Grade de tamanhos padronizada no cadastro de produtos de todos os fornecedores."},"st":"mod","sub":"Retirar do seletor os tamanhos indisponíveis em vez de listá-los desabilitados.","ops":["U10","U02"],"c2":{"c":"C36","t":"Produtos com numeração (36, 38, 40) e com letras convivem, e a ordem natural de um não serve ao outro.","mit":"Ordenação por tipo de grade, definida no cadastro."},"cf":"Sem intervenção, a escolha fica lenta e aumentam as compras no tamanho errado.","lim":{"l":"L06","t":"Depende de os fornecedores cadastrarem a grade no padrão."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se a lentidão vier da dúvida sobre qual tamanho serve, e não da ordem.","conf":"alta"},
{"id":61,"h":2,"sev":3,"t":"Siglas internas sem explicação","sym":"O plano de saúde mostra “CID”, “TUSS” e “OPME” para beneficiários leigos.","ten":"As siglas economizam espaço, mas nem todos as conhecem.","sol":"Reenquadrar para o beneficiário: escrever por extenso (“código da doença”, “material cirúrgico”) em todo o portal.","c":"C25","u":"U04","e":"macro","i":"I03","m":"Dúvidas sobre termos","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["WC3.1","BS7","GP5","SH2","GP4"],"dom":"saude","vul":"idosos","ag":"Ganha: beneficiários. Perde: o termo simplificado pode não corresponder ao documento oficial.","alt":"E se os termos forem obrigatórios por regulação?","esc":{"micro":"Termo comum com o técnico entre parênteses.","meso":"Glossário no próprio portal.","macro":"Reenquadrar para o beneficiário: escrever por extenso (“código da doença”, “material cirúrgico”) em todo o portal."},"st":"sub","sub":"Remover siglas da tela principal.","ops":["U09","U30"],"c2":{"c":"C23","t":"Termos simplificados podem não corresponder ao documento oficial.","mit":"Manter o termo oficial no detalhe."},"cf":"Sem intervenção, beneficiários não entendem o que foi autorizado.","lim":{"l":"L06","t":"Normas da agência reguladora."},"ide":{"mais":["I03","I06"],"menos":["I04"]},"ref":"Estaria errada se o público já conhecer as siglas.","conf":"alta"},
{"id":62,"h":2,"sev":4,"t":"Diálogo com “OK” e “Cancelar” ambíguos","sym":"No streaming: “Deseja cancelar a assinatura?” — OK / Cancelar.","ten":"Os botões genéricos são padrão, mas a pergunta muda seu sentido.","sol":"Converter a função dos botões: cada um diz o que faz — “Cancelar assinatura” / “Manter assinatura”.","c":"C08","u":"U17","e":"micro","i":"I04","m":"Escolhas equivocadas em diálogos","freq":3,"imp":3,"pers":2,"pf":"P01","hx":["BS7","DN7","WC3.2","ISO3","GP5"],"dom":"comunicacao","vul":"","ag":"Ganha: quem assina o serviço. Perde: nada.","alt":"E se o diálogo em si for desnecessário?","esc":{"micro":"Converter a função dos botões: cada um diz o que faz — “Cancelar assinatura” / “Manter assinatura”.","meso":"Revisar todos os diálogos com verbos de ação.","macro":"Regra de escrita: botão sempre com verbo específico."},"st":"mod","sub":"Remover o diálogo de confirmação quando houver desfazer.","ops":["U04","U30"],"c2":{"c":"C35","t":"Botões longos quebram layouts pequenos.","mit":"Verbos curtos e específicos."},"cf":"Sem intervenção, pessoas cancelam sem querer.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se os cancelamentos forem intencionais.","conf":"alta"},
{"id":63,"h":2,"sev":2,"t":"Anglicismos desnecessários","sym":"A plataforma de cursos usa “Dashboard”, “Upgrade” e “Checkout” para um público que não fala inglês.","ten":"O time usa termos em inglês, mas o público pensa em português.","sol":"Reenquadrar em português do público — “Painel”, “Mudar de plano”, “Finalizar compra” — com glossário de produto.","c":"C24","u":"U04","e":"macro","i":"I03","m":"Compreensão em teste","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["WC3.1","BS8","GP5","ISO3"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: nada.","alt":"E se o público for jovem e usar esses termos?","esc":{"micro":"Trocar os anglicismos mais visíveis.","meso":"Revisar todo o fluxo de compra.","macro":"Reenquadrar em português do público — “Painel”, “Mudar de plano”, “Finalizar compra” — com glossário de produto."},"st":"mod","sub":"Remover anglicismos desnecessários.","ops":["U26","U30"],"c2":{"c":"C21","t":"O público pode mudar e passar a usar os termos em inglês.","mit":"Testar periodicamente."},"cf":"Sem intervenção, parte do público não entende as telas.","lim":{"l":"L07","t":"Diferenças de repertório entre públicos."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se o teste mostrar compreensão alta.","conf":"média"},
{"id":64,"h":2,"sev":3,"t":"Categorias pelo fornecedor","sym":"A loja organiza produtos por marca do fabricante, não por uso.","ten":"O estoque é gerido por fornecedor, mas o cliente procura por necessidade.","sol":"Categorias por uso e ocasião, com a marca como filtro secundário.","c":"C11","u":"U10","e":"meso","i":"I03","m":"Tempo até encontrar o produto","freq":2,"imp":2,"pers":2,"pf":"P02","hx":["GP6","BS8","BS1.2","ISO1","LX2"],"dom":"comercio","vul":"","ag":"Ganha: quem compra por necessidade. Perde: marcas que pagavam por destaque na vitrine.","alt":"E se boa parte do público procurar por marca? Então o problema é oferecer os dois caminhos.","esc":{"micro":"Filtro por marca dentro de cada categoria.","meso":"Categorias por uso e ocasião, com a marca como filtro secundário.","macro":"Pesquisa de busca e navegação real para desenhar as categorias."},"st":"mod","sub":"Retirar o menu por fornecedor da navegação principal.","ops":["U02","U26"],"c2":{"c":"C26","t":"Fornecedores que pagavam por visibilidade perdem destaque.","mit":"Espaço patrocinado identificado dentro das categorias por uso."},"cf":"Sem intervenção, quem não conhece as marcas não encontra o que precisa.","lim":{"l":"L06","t":"Contratos comerciais com fornecedores."},"ide":{"mais":["I03"],"menos":["I02"]},"ref":"Estaria errada se a análise de busca mostrar que a maioria procura por marca.","conf":"alta"},
{"id":65,"h":2,"sev":3,"t":"Preço sem impostos e taxas","sym":"A passagem anunciada não inclui taxas que só aparecem no fim.","ten":"A precificação tem componentes, mas o cliente pensa no preço final.","sol":"Redistribuir o custo da surpresa: preço único com taxas incluídas desde a busca.","c":"C26","u":"U15","e":"macro","i":"I06","m":"Abandono por preço final","freq":3,"imp":2,"pers":2,"pf":"P09","hx":["DP3","GP2","ISO3","SH2","LX8"],"dom":"mobilidade","vul":"","ag":"Ganha: quem viaja. Perde: a companhia perde o preço “isca”.","alt":"E se as taxas forem de terceiros e variarem?","esc":{"micro":"Preço total com taxas já na lista de resultados da busca.","meso":"Detalhamento das taxas sob demanda.","macro":"Redistribuir o custo da surpresa: preço único com taxas incluídas desde a busca."},"st":"sub","sub":"A própria solução é subtrativa: elimina taxas separadas.","ops":["U01","U30"],"c2":{"c":"C20","t":"Preço total parece mais caro que o dos concorrentes.","mit":"Destacar “preço final”."},"cf":"Sem intervenção, desconfiança e abandono.","lim":{"l":"L06","t":"Regras de publicidade."},"ide":{"mais":["I06"],"menos":["I02"]},"ref":"Estaria errada se as pessoas preferirem ver as taxas separadas.","conf":"alta"},
{"id":66,"h":2,"sev":3,"t":"Endereço que não aceita “sem número”","sym":"No cadastro da unidade de saúde, o número do endereço é obrigatório e só aceita dígitos.","ten":"O formulário supõe endereços urbanos padronizados, mas o país é diverso.","sol":"Aceitar “s/n”, complementos livres e endereços rurais com ponto de referência.","c":"C22","u":"U29","e":"micro","i":"I06","m":"Cadastros com endereço improvisado","freq":2,"imp":2,"pers":2,"pf":"P09","hx":["LX7","BS8","SH2","WC3.3","ISO6"],"dom":"saude","vul":"zona rural","ag":"Ganha: moradores de área rural. Perde: parte da padronização do dado.","alt":"E se o endereço for usado para visitas? Então o ponto de referência é mais útil que o número.","esc":{"micro":"Aceitar “s/n”, complementos livres e endereços rurais com ponto de referência.","meso":"Campo de ponto de referência.","macro":"Georreferenciamento das moradias rurais."},"st":"sub","sub":"Remover a obrigatoriedade do número.","ops":["U22","U16"],"c2":{"c":"C34","t":"Endereços livres são mais difíceis de localizar.","mit":"Pedir ponto de referência."},"cf":"Sem intervenção, cadastros ficam com endereço inventado.","lim":{"l":"L06","t":"Padrões do cadastro nacional."},"ide":{"mais":["I06"],"menos":["I04"]},"ref":"Estaria errada se os endereços sem número forem raros no público.","conf":"alta"},
{"id":67,"h":2,"sev":3,"t":"Nome dividido em primeiro e último","sym":"Na matrícula, “Maria da Conceição dos Santos” não cabe em “Nome / Sobrenome”.","ten":"O sistema estrangeiro pensa em dois nomes; aqui nomes são compostos.","sol":"Separar funções: nome civil completo para documentos e nome social para a convivência, cada um onde deve.","c":"C23","u":"U09","e":"macro","i":"I06","m":"Nomes cortados ou trocados","freq":2,"imp":2,"pers":2,"pf":"P09","hx":["IA6","BS8","SH2","ISO3"],"dom":"educacao","vul":"pessoas trans","ag":"Ganha: estudantes, inclusive pessoas trans. Perde: os sistemas precisam separar nome civil e nome social.","alt":"E se o nome for usado para documentos oficiais?","esc":{"micro":"Campo único de nome completo.","meso":"Nome social usado em toda a comunicação.","macro":"Separar funções: nome civil completo para documentos e nome social para a convivência, cada um onde deve."},"st":"sub","sub":"Remover a divisão nome/sobrenome.","ops":["U29","U30"],"c2":{"c":"C23","t":"Documentos exigem o nome civil.","mit":"Guardar os dois e usar cada um no lugar certo."},"cf":"Sem intervenção, nomes ficam cortados e pessoas são chamadas pelo nome errado.","lim":{"l":"L06","t":"Normas de registro acadêmico."},"ide":{"mais":["I06"],"menos":["I03"]},"ref":"Estaria errada se a instituição não usar o nome em comunicação.","conf":"alta"},
{"id":68,"h":2,"sev":2,"t":"Telefone sem DDD claro","sym":"No cadastro de paciente, o telefone aceita 8 ou 9 dígitos sem indicar DDD; metade dos números fica incompleta.","ten":"O telefone tem formato próprio no país, e o campo o ignora.","sol":"Máscara (00) 00000-0000 e validação do DDD.","c":"C22","u":"U21","e":"micro","i":"I04","m":"Telefones inválidos na base","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["DN3","WC3.3","BS5.1","LX7"],"dom":"saude","vul":"","ag":"Ganha: pacientes, que recebem avisos do laboratório. Perde: uma máscara fixa quebra números estrangeiros e ramais.","alt":"E se o telefone não for o melhor canal (paciente sem celular, número compartilhado)?","esc":{"micro":"Máscara (00) 00000-0000 e validação do DDD.","meso":"Aceitar mais de um contato e indicar o preferido.","macro":"Números internacionais com seleção de país."},"st":"mod","sub":"Retirar a exigência de digitar parênteses e hífen: a máscara formata sozinha.","ops":["U20","U16"],"c2":{"c":"C29","t":"Uma máscara fixa quebra números estrangeiros e ramais.","mit":"Detectar o país e aceitar ramal em campo próprio."},"cf":"Sem intervenção, resultados de exames e remarcações não chegam ao paciente.","lim":{"l":"L07","t":"Pacientes podem não saber o DDD de um número emprestado."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se os números inválidos vierem de telefones desativados, e não de digitação.","conf":"alta"},
{"id":69,"h":2,"sev":3,"t":"Gênero binário obrigatório","sym":"O app de recomendação exige “Masculino/Feminino” para personalizar sugestões.","ten":"O sistema pede o dado por hábito, mas ele exclui e nem sempre é necessário.","sol":"Reorientar: perguntar para que o dado serve; remover o campo e personalizar por preferências declaradas.","c":"C19","u":"U06","e":"macro","i":"I06","m":"Desistências no cadastro","freq":2,"imp":2,"pers":2,"pf":"P16","hx":["IA6","SH2","DP5","ISO1"],"dom":"ia","vul":"pessoas não binárias","ag":"Ganha: todas as pessoas. Perde: a personalização perde uma variável.","alt":"E se o gênero for usado para recomendações estereotipadas?","esc":{"micro":"Tornar o campo opcional e explicar para que serve.","meso":"Recomendações baseadas em preferências declaradas, sem inferência por gênero.","macro":"Reorientar: perguntar para que o dado serve; remover o campo e personalizar por preferências declaradas."},"st":"sub","sub":"A própria solução é subtrativa: remove o campo.","ops":["U27","U28"],"c2":{"c":"C34","t":"Sem o dado, algumas recomendações ficam genéricas.","mit":"Usar preferências explícitas."},"cf":"Sem intervenção, pessoas desistem e o sistema reproduz estereótipos.","lim":{"l":"L06","t":"Leis de proteção de dados."},"ide":{"mais":["I06"],"menos":["I01"]},"ref":"Estaria errada se o dado for realmente necessário.","conf":"média"},
{"id":70,"h":2,"sev":3,"t":"Metáfora de carrinho num agendamento","sym":"Para marcar a visita do técnico de internet, “adicione ao carrinho”.","ten":"A plataforma reaproveita a estrutura de loja, mas a tarefa é outra.","sol":"Separar funções: agendamento com fluxo próprio, fora da loja, na linguagem da visita técnica.","c":"C35","u":"U04","e":"meso","i":"I03","m":"Erros de percurso no agendamento","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["TG12","DN8","GP5","BS8"],"dom":"casa","vul":"","ag":"Ganha: quem agenda o serviço. Perde: nada relevante.","alt":"E se o agendamento vier junto com a compra de equipamento? Então o carrinho faz sentido só nesse caso.","esc":{"micro":"Linguagem da tarefa real: “Escolher horário”, “Confirmar visita”.","meso":"Separar funções: agendamento com fluxo próprio, fora da loja, na linguagem da visita técnica.","macro":"Visita marcada automaticamente na compra do plano, com opção de escolher horário."},"st":"sub","sub":"Retirar o carrinho do fluxo de agendamento.","ops":["U09","U10"],"c2":{"c":"C11","t":"Quando a visita tem custo, o fluxo precisa de pagamento.","mit":"Pagamento no fim do agendamento, sem a metáfora de carrinho."},"cf":"Sem intervenção, as pessoas se perdem num fluxo de compra para algo que não é compra.","lim":{"l":"L03","t":"Depende de a plataforma permitir fluxos diferentes do de loja."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se as pessoas não tiverem dificuldade em teste.","conf":"média"},
{"id":71,"h":2,"sev":2,"t":"Arquivos nomeados por identificador","sym":"No sistema de contratos, os anexos aparecem como “doc_88213_v2_final.pdf”.","ten":"O sistema identifica por código, mas as pessoas reconhecem por nome e data.","sol":"Mostrar título legível, autor e data; o identificador fica nos detalhes.","c":"C10","u":"U16","e":"micro","i":"I03","m":"Tempo para achar um arquivo","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP5","BS7","WC1.1","ISO2"],"dom":"trabalho","vul":"","ag":"Ganha: quem procura documentos. Perde: nada relevante.","alt":"E se os nomes técnicos vierem de outro sistema que gera os arquivos?","esc":{"micro":"Mostrar título legível, autor e data; o identificador fica nos detalhes.","meso":"Busca pelo conteúdo do documento, e não pelo nome.","macro":"Metadados obrigatórios (título, cliente, data) na origem dos arquivos."},"st":"mod","sub":"Retirar o identificador da lista principal e deixá-lo nos detalhes.","ops":["U12","U02"],"c2":{"c":"C05","t":"Títulos legíveis podem se repetir (“Contrato”, “Contrato”).","mit":"Mostrar título, autor e data juntos."},"cf":"Sem intervenção, a equipe abre vários arquivos até achar o certo.","lim":{"l":"L06","t":"O sistema de origem pode não permitir títulos."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se a equipe usar os códigos para referência cruzada no dia a dia.","conf":"alta"},
{"id":72,"h":2,"sev":3,"t":"Horário em AM/PM","sym":"“08:00 PM” no calendário da empresa gera reuniões marcadas às 8 da manhã.","ten":"O componente veio pronto no padrão americano.","sol":"Usar o formato de 24 horas do país (20:00) e manter AM/PM só quando a região pedir.","c":"C29","u":"U21","e":"micro","i":"I04","m":"Compromissos no horário errado","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["BS8","ISO3","WC3.1","LX4"],"dom":"trabalho","vul":"","ag":"Ganha: quem marca reuniões. Perde: nada relevante.","alt":"E se a equipe for internacional e cada um ler de um jeito?","esc":{"micro":"Usar o formato de 24 horas do país (20:00) e manter AM/PM só quando a região pedir.","meso":"Preferência de formato por pessoa, com o fuso ao lado.","macro":"Padrão da empresa definido nas configurações globais."},"st":"mod","sub":"Retirar o AM/PM como padrão do componente.","ops":["U12","U30"],"c2":{"c":"C29","t":"Parceiros dos EUA passam a ver 24 horas.","mit":"Formato definido pela preferência de cada pessoa."},"cf":"Sem intervenção, reuniões são marcadas no horário errado.","lim":{"l":"L03","t":"O componente pronto pode não suportar troca de formato."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se os erros vierem de fuso horário, e não do formato.","conf":"alta"},
{"id":73,"h":2,"sev":2,"t":"Medidas em polegadas e libras","sym":"A loja brasileira mostra “15 in” e “3 lb”.","ten":"O catálogo veio do fabricante estrangeiro.","sol":"Converter para centímetros e quilos; manter a medida original entre parênteses quando for referência de mercado.","c":"C24","u":"U16","e":"micro","i":"I03","m":"Dúvidas sobre medidas","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP4","BS8","MB2","DN8"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada relevante.","alt":"E se a medida estrangeira for a referência do mercado (TV em polegadas)?","esc":{"micro":"Converter para centímetros e quilos; manter a medida original entre parênteses quando for referência de mercado.","meso":"Comparação com objetos conhecidos (“cabe numa mochila”).","macro":"Padrão de unidades no cadastro de produtos importados."},"st":"mod","sub":"Retirar polegadas e libras da ficha principal, exceto onde forem referência de mercado.","ops":["U12","U30"],"c2":{"c":"C35","t":"A conversão gera números quebrados (38,1 cm).","mit":"Arredondar com cuidado e manter a original entre parênteses."},"cf":"Sem intervenção, as pessoas erram a compra e devolvem.","lim":{"l":"L06","t":"Depende dos dados enviados pelo fabricante."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se o público do produto for técnico e preferir a unidade original.","conf":"alta"},
{"id":74,"h":2,"sev":3,"t":"Pastas pelo tipo, não pelo projeto","sym":"Os arquivos ficam separados em “PDFs”, “Imagens” e “Planilhas”.","ten":"A estrutura técnica é simples, mas as pessoas pensam por projeto.","sol":"Organizar por projeto ou cliente, com filtro por tipo dentro de cada um.","c":"C11","u":"U11","e":"meso","i":"I03","m":"Tempo para localizar material","freq":2,"imp":2,"pers":2,"pf":"P02","hx":["GP6","BS1.2","DN8","ISO1"],"dom":"trabalho","vul":"","ag":"Ganha: equipes de projeto. Perde: quem se acostumou às pastas por tipo.","alt":"E se o mesmo arquivo pertencer a vários projetos?","esc":{"micro":"Filtro por tipo dentro de cada projeto.","meso":"Organizar por projeto ou cliente, com filtro por tipo dentro de cada um.","macro":"Etiquetas em vez de pastas: um arquivo, vários contextos."},"st":"mod","sub":"Retirar as pastas por tipo do nível principal.","ops":["U10","U34"],"c2":{"c":"C12","t":"Arquivos de vários projetos se duplicam nas pastas.","mit":"Etiquetas em vez de cópias."},"cf":"Sem intervenção, material se perde e é refeito.","lim":{"l":"L07","t":"Mudar hábitos de organização da equipe leva tempo."},"ide":{"mais":["I03"],"menos":["I02"]},"ref":"Estaria errada se a equipe buscar arquivos por tipo (todas as planilhas).","conf":"alta"},
{"id":75,"h":2,"sev":2,"t":"Mensagem de sucesso técnica","sym":"“Registro inserido com sucesso na base.”","ten":"A mensagem descreve o banco de dados, não o que a pessoa fez.","sol":"Converter a perda em ganho: a confirmação vira próximo passo — “Cliente cadastrado. Enviar boas-vindas?”","c":"C35","u":"U18","e":"micro","i":"I03","m":"Compreensão da confirmação","freq":2,"imp":1,"pers":2,"pf":"P03","hx":["GP5","BS7","SH4","ISO2"],"dom":"trabalho","vul":"","ag":"Ganha: quem cadastra clientes. Perde: nada relevante.","alt":"E se a mensagem for dispensável e a própria tela do cliente for a confirmação?","esc":{"micro":"Converter a perda em ganho: a confirmação vira próximo passo — “Cliente cadastrado. Enviar boas-vindas?”","meso":"Próximos passos sugeridos após cada cadastro.","macro":"Padrão de mensagens de sucesso na linguagem da tarefa."},"st":"mod","sub":"Retirar a mensagem técnica.","ops":["U04","U20"],"c2":{"c":"C17","t":"Sugestões de próxima ação podem distrair de quem ia cadastrar vários clientes.","mit":"Uma sugestão só, dispensável, e “Cadastrar outro” em destaque."},"cf":"Sem intervenção, a mensagem confunde e não ajuda a continuar.","lim":{"l":"L03","t":"Nenhuma barreira técnica; depende de revisar os textos."},"ide":{"mais":["I03","I02"],"menos":[]},"ref":"Estaria errada se o rastreamento de cliques mostrar que ninguém usa a sugestão de próxima ação.","conf":"alta"},
{"id":76,"h":2,"sev":3,"t":"Agendamento pede médico antes do sintoma","sym":"Para marcar consulta é preciso escolher um médico pelo nome.","ten":"O sistema é organizado por profissional, mas o paciente parte do problema.","sol":"Começar pela necessidade (especialidade ou sintoma), depois data e profissional.","c":"C32","u":"U10","e":"meso","i":"I02","m":"Agendamentos na especialidade errada","freq":3,"imp":2,"pers":2,"pf":"P02","hx":["ISO1","BS8","GP1","DN8"],"dom":"saude","vul":"","ag":"Ganha: pacientes e o serviço, com menos marcações erradas. Perde: a triagem por sintoma pode indicar a especialidade errada.","alt":"E se a pessoa já tiver um médico de confiança?","esc":{"micro":"Busca por sintoma ou especialidade no início.","meso":"Começar pela necessidade (especialidade ou sintoma), depois data e profissional.","macro":"Triagem por enfermagem para casos incertos."},"st":"mod","sub":"Retirar a escolha do médico como primeira etapa obrigatória.","ops":["U02","U13"],"c2":{"c":"C27","t":"A triagem por sintoma pode indicar a especialidade errada.","mit":"Confirmação ou redirecionamento pela equipe."},"cf":"Sem intervenção, pacientes são atendidos na especialidade errada e voltam à fila.","lim":{"l":"L06","t":"Regras do conselho de medicina sobre triagem."},"ide":{"mais":["I02"],"menos":["I04"]},"ref":"Estaria errada se a maioria dos pacientes já souber qual médico procurar.","conf":"alta"},
{"id":77,"h":2,"sev":2,"t":"Rastreio com jargão logístico","sym":"“Objeto encaminhado para CDD — Unidade de Tratamento.”","ten":"A logística tem vocabulário próprio, mas o cliente quer saber quando chega.","sol":"Traduzir para linguagem comum (“Saiu do centro de distribuição”) com previsão de entrega.","c":"C25","u":"U04","e":"meso","i":"I03","m":"Contatos sobre rastreio","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["WC3.1","GP5","BS7","ISO2"],"dom":"comercio","vul":"","ag":"Ganha: clientes. Perde: detalhes logísticos úteis em atrasos ficam escondidos.","alt":"E se o cliente só quiser saber a data de chegada?","esc":{"micro":"Status em linguagem comum.","meso":"Traduzir para linguagem comum (“Saiu do centro de distribuição”) com previsão de entrega.","macro":"Padrão de eventos combinado com a transportadora."},"st":"mod","sub":"Retirar os termos logísticos da tela do cliente.","ops":["U16","U30"],"c2":{"c":"C34","t":"Simplificar esconde detalhes úteis em atrasos.","mit":"Detalhes técnicos sob demanda."},"cf":"Sem intervenção, o suporte é acionado para traduzir o rastreio.","lim":{"l":"L06","t":"Depende dos códigos da transportadora."},"ide":{"mais":["I03"],"menos":["I09"]},"ref":"Estaria errada se os contatos forem sobre atrasos, e não sobre termos.","conf":"alta"},
{"id":78,"h":2,"sev":3,"t":"Tamanho de roupa sem medidas","sym":"Apenas “P, M, G”; cada marca veste diferente.","ten":"A etiqueta é padrão da marca, mas o corpo é medido em centímetros.","sol":"Inferir o tamanho: recomendação por altura e peso, com a tabela de medidas em centímetros ao lado.","c":"C34","u":"U02","e":"meso","i":"I04","m":"Trocas por tamanho","freq":3,"imp":2,"pers":2,"pf":"P06","hx":["GP4","GP1","IA4","TG1"],"dom":"comercio","vul":"","ag":"Ganha: quem compra roupas. Perde: a loja precisa manter medidas por peça.","alt":"E se as medidas variarem entre lotes do mesmo produto?","esc":{"micro":"Tabela de medidas em centímetros por peça.","meso":"Inferir o tamanho: recomendação por altura e peso, com a tabela de medidas em centímetros ao lado.","macro":"Padrão de medidas entre marcas vendidas na loja."},"st":"add","sub":"Retirar do catálogo peças com alta taxa de troca até revisar as medidas.","ops":["U01","U26"],"c2":{"c":"C06","t":"Recomendações erradas geram trocas e desconfiança.","mit":"Mostrar a confiança da recomendação e aprender com as trocas."},"cf":"Sem intervenção, trocas frequentes corroem a margem.","lim":{"l":"L04","t":"Medir cada peça tem custo."},"ide":{"mais":["I04"],"menos":["I05"]},"ref":"Estaria errada se as trocas vierem de defeitos ou de gosto, e não de tamanho.","conf":"média"},
{"id":79,"h":2,"sev":3,"t":"Foto sem referência de escala","sym":"A luminária parece grande na foto e chega do tamanho de uma caneca.","ten":"A foto valoriza o produto, mas a percepção de tamanho engana.","sol":"Foto em contexto de uso ou ao lado de objeto conhecido, com medidas visíveis.","c":"C34","u":"U16","e":"micro","i":"I04","m":"Devoluções por expectativa","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["GP4","WC1.1","BS8","ISO2"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: a loja tem custo de fotografia.","alt":"E se o problema for a descrição, que não traz as medidas?","esc":{"micro":"Foto em contexto de uso ou ao lado de objeto conhecido, com medidas visíveis.","meso":"Vídeo curto mostrando o produto em uso.","macro":"Padrão fotográfico com objeto de referência."},"st":"add","sub":"Retirar fotos que distorcem a escala (grande-angulares, recortadas).","ops":["U01","U30"],"c2":{"c":"C04","t":"Fotos em ambientes montados também enganam.","mit":"Medidas visíveis sobre a foto."},"cf":"Sem intervenção, devoluções por expectativa continuam.","lim":{"l":"L04","t":"Custo de produção de fotos."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se as devoluções vierem de defeitos.","conf":"alta"},
{"id":80,"h":2,"sev":2,"t":"Lista ordenada pelo sobrenome","sym":"A lista de chamada ordena por sobrenome, mas a turma se conhece pelo primeiro nome.","ten":"O padrão estrangeiro ordena por sobrenome; o costume local é outro.","sol":"Ordenar pelo nome como as pessoas se chamam, com opção de mudar a ordem.","c":"C24","u":"U21","e":"micro","i":"I03","m":"Tempo para achar uma pessoa","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS8","GP6","ISO3","TG5"],"dom":"educacao","vul":"","ag":"Ganha: professores. Perde: nada relevante.","alt":"E se a ordem por sobrenome for exigida em documentos oficiais?","esc":{"micro":"Ordenar pelo nome como as pessoas se chamam, com opção de mudar a ordem.","meso":"Preferência de ordenação por professor.","macro":"Padrão da instituição para telas e outro para documentos."},"st":"mod","sub":"Retirar a ordenação fixa por sobrenome das telas de chamada.","ops":["U11","U14"],"c2":{"c":"C29","t":"Documentos oficiais pedem sobrenome.","mit":"Ordem própria na geração dos documentos."},"cf":"Sem intervenção, a chamada fica lenta.","lim":{"l":"L06","t":"Normas da secretaria acadêmica."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se a turma se chamar pelo sobrenome.","conf":"alta"},
{"id":81,"h":2,"sev":4,"t":"Linguagem que ignora o público","sym":"O assistente de voz usa gírias e respostas rápidas com idosos.","ten":"O produto foi desenhado pela equipe, para a equipe.","sol":"Sondar antes de lançar: testar com idosos e ajustar linguagem, ritmo e confirmações ao público real.","c":"C25","u":"U25","e":"macro","i":"I06","m":"Sucesso em tarefas com o público-alvo","freq":2,"imp":3,"pers":3,"pf":"P10","hx":["IA5","SH2","WC3.1","BS8","ISO7"],"dom":"ia","vul":"idosos","ag":"Ganha: idosos. Perde: a equipe precisa pesquisar com públicos diferentes.","alt":"E se o assistente precisar se adaptar a cada pessoa?","esc":{"micro":"Respostas curtas e claras.","meso":"Ritmo mais lento e confirmações.","macro":"Sondar antes de lançar: testar com idosos e ajustar linguagem, ritmo e confirmações ao público real."},"st":"add","sub":"Remover gírias e respostas rápidas demais.","ops":["U34","U21"],"c2":{"c":"C21","t":"Adaptar o tom pode parecer condescendente.","mit":"Deixar a pessoa escolher o estilo."},"cf":"Sem intervenção, idosos abandonam o assistente.","lim":{"l":"L07","t":"Diversidade de públicos."},"ide":{"mais":["I06"],"menos":["I02"]},"ref":"Estaria errada se os idosos gostarem do estilo.","conf":"média"},
{"id":82,"h":2,"sev":2,"t":"Ícones de tecnologias obsoletas","sym":"O editor de redação escolar usa um disquete para salvar; estudantes nunca viram um.","ten":"O ícone virou convenção, mas o objeto que representa sumiu.","sol":"Selecionar: eliminar o botão com disquete e salvar automaticamente, com indicador de estado.","c":"C36","u":"U35","e":"micro","i":"I11","m":"Reconhecimento por faixa etária","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["TG12","BS7","GP5","TG11"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: nada relevante.","alt":"E se o salvamento já for automático? Então o botão é resíduo.","esc":{"micro":"Selecionar: eliminar o botão com disquete e salvar automaticamente, com indicador de estado.","meso":"Salvamento automático com indicador de estado.","macro":"Revisão periódica de ícones do produto."},"st":"sub","sub":"A própria solução é subtrativa: remove o botão salvar.","ops":["U16","U12"],"c2":{"c":"C34","t":"Sem botão, as pessoas não sabem se salvou.","mit":"Indicador “Salvo às 14:32”."},"cf":"Sem intervenção, estudantes não reconhecem a função.","lim":{"l":"L03","t":"Exige salvamento automático confiável."},"ide":{"mais":["I11"],"menos":[]},"ref":"Estaria errada se os estudantes reconhecerem o disquete em teste.","conf":"alta"},
{"id":83,"h":2,"sev":3,"t":"Escala de avaliação invertida","sym":"Na pesquisa do serviço público, 1 é “ótimo” e 5 é “péssimo”.","ten":"A escala foi herdada de outro sistema, contra a expectativa comum.","sol":"Instituir um padrão em todo o órgão: mais estrelas = melhor, com rótulos nas extremidades.","c":"C05","u":"U30","e":"macro","i":"I04","m":"Respostas incoerentes","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS6","ISO3","GP2","SH1"],"dom":"publico","vul":"","ag":"Ganha: gestores e cidadãos. Perde: a mudança quebra a comparação com pesquisas antigas.","alt":"E se a escala for obrigatória?","esc":{"micro":"Rótulos nas extremidades.","meso":"Escala padrão no órgão.","macro":"Instituir um padrão em todo o órgão: mais estrelas = melhor, com rótulos nas extremidades."},"st":"mod","sub":"Remover escalas invertidas.","ops":["U04","U26"],"c2":{"c":"C36","t":"Mudar a escala quebra comparações históricas.","mit":"Converter os dados antigos."},"cf":"Sem intervenção, respostas incoerentes.","lim":{"l":"L06","t":"Normas internas de pesquisa do órgão e comparabilidade com anos anteriores."},"ide":{"mais":["I04"],"menos":["I09"]},"ref":"Estaria errada se as respostas forem coerentes.","conf":"média"},
{"id":84,"h":2,"sev":4,"t":"Variação financeira só por cor","sym":"A carteira de investimentos mostra “3,2%” em verde ou vermelho, sem sinal.","ten":"A cor carrega o sentido, mas nem todos a distinguem.","sol":"Sinal explícito (+3,2% / −3,2%), seta e cor como reforço.","c":"C01","u":"U22","e":"micro","i":"I04","m":"Leituras erradas de variação","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG3","WC1.4","GP9","GP10"],"dom":"financas","vul":"daltonismo","ag":"Ganha: pessoas com daltonismo e quem lê em telas ruins. Perde: a tabela ganha sinais e setas extras.","alt":"E se a cor for usada como único sinal em outras telas também?","esc":{"micro":"Sinal explícito (+3,2% / −3,2%), seta e cor como reforço.","meso":"Padrão de variação com sinal e seta em todo o app.","macro":"Guia de acessibilidade com auditoria periódica."},"st":"add","sub":"Retirar a cor como único portador do sentido.","ops":["U16","U30"],"c2":{"c":"C17","t":"Muitos sinais juntos poluem a tabela.","mit":"Sinal e seta pequenos, cor como reforço."},"cf":"Sem intervenção, investidores leem ganho como perda.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I04","I06"],"menos":["I03"]},"ref":"Estaria errada se ninguém tiver dificuldade em teste com daltônicos.","conf":"alta"},
{"id":85,"h":2,"sev":3,"t":"Login pela matrícula","sym":"O sistema acadêmico exige a matrícula de 11 dígitos, que ninguém sabe de cor.","ten":"O sistema identifica pelo registro interno; a pessoa se identifica pelo e-mail ou CPF.","sol":"Aceitar e-mail ou CPF como login; a matrícula continua como identificador interno.","c":"C28","u":"U16","e":"meso","i":"I02","m":"Recuperações de acesso","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS8","ISO1","GP1","SH8"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: cPF como login levanta preocupação de privacidade.","alt":"E se a matrícula for necessária para outros sistemas?","esc":{"micro":"Aceitar e-mail como login.","meso":"Aceitar e-mail ou CPF como login; a matrícula continua como identificador interno.","macro":"Login único da instituição."},"st":"mod","sub":"Retirar a matrícula como único login.","ops":["U02","U12"],"c2":{"c":"C05","t":"CPF como login levanta preocupação de privacidade.","mit":"Oferecer e-mail como alternativa."},"cf":"Sem intervenção, recuperações de acesso lotam o suporte no início do semestre.","lim":{"l":"L06","t":"Normas de TI da instituição."},"ide":{"mais":["I02"],"menos":["I05"]},"ref":"Estaria errada se a matrícula estiver impressa na carteirinha que todos carregam.","conf":"alta"},
{"id":86,"h":2,"sev":2,"t":"Prazos em horas","sym":"“O técnico da internet vem em até 72h”: é sexta ou segunda?","ten":"O prazo é calculado em horas, mas pessoas planejam em dias.","sol":"Converter para data concreta: “Chega até sexta, 26/09”.","c":"C32","u":"U16","e":"micro","i":"I03","m":"Dúvidas sobre prazo","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP4","BS8","GP1","GP2"],"dom":"casa","vul":"","ag":"Ganha: clientes. Perde: nada relevante.","alt":"E se o prazo for incerto por natureza?","esc":{"micro":"Converter para data concreta: “Chega até sexta, 26/09”.","meso":"Agendamento com janela de horário.","macro":"Padrão de prazos em datas em toda a comunicação."},"st":"mod","sub":"Retirar prazos em horas das mensagens ao cliente.","ops":["U20","U02"],"c2":{"c":"C27","t":"Datas concretas podem não ser cumpridas.","mit":"Janela realista e aviso de atraso."},"cf":"Sem intervenção, a pessoa fica em casa esperando sem saber o dia.","lim":{"l":"L05","t":"A agenda dos técnicos muda ao longo do dia."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se as pessoas preferirem prazos em horas.","conf":"alta"},
{"id":87,"h":2,"sev":2,"t":"“Submeter” como botão","sym":"O botão do formulário público traduz literalmente “Submit” como “Submeter”.","ten":"A tradução foi literal; em português a palavra soa estranha e autoritária.","sol":"Verbos naturais que dizem o resultado: “Enviar”, “Cadastrar”, “Publicar”.","c":"C24","u":"U04","e":"micro","i":"I03","m":"Estranhamento em teste","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS7","GP5","WC3.1","ISO3"],"dom":"publico","vul":"baixa escolaridade","ag":"Ganha: cidadãos. Perde: nada relevante.","alt":"E se o termo for padrão da área de TI do órgão?","esc":{"micro":"Verbos naturais que dizem o resultado: “Enviar”, “Cadastrar”, “Publicar”.","meso":"Revisar todos os botões dos formulários.","macro":"Guia de escrita do órgão com lista de verbos recomendados para botões, revisado por linguagem simples."},"st":"mod","sub":"Retirar “submeter” dos botões.","ops":["U30","U35"],"c2":{"c":"C35","t":"Termos novos podem não ser entendidos.","mit":"Testar os novos rótulos com cidadãos antes de trocar em todo o portal."},"cf":"Sem intervenção, o estranhamento reduz a confiança.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se a troca de “Submeter” por “Enviar” não mudar a taxa de conclusão nem a avaliação do serviço.","conf":"alta"},
{"id":88,"h":2,"sev":3,"t":"Tradução automática sem revisão","sym":"O app usa tradução automática com erros como “Por favor, entre sua conta”.","ten":"Traduzir tudo é rápido, mas os erros minam a confiança.","sol":"Refutar antes de publicar: revisão por falantes nativos e testes de leitura com o público local, com glossário.","c":"C09","u":"U27","e":"macro","i":"I04","m":"Erros de tradução por tela","freq":2,"imp":2,"pers":3,"pf":"P15","hx":["WC3.1","GP2","ISO7","IA2"],"dom":"ia","vul":"estrangeiros","ag":"Ganha: quem lê. Perde: custo de revisão.","alt":"E se a tradução automática for boa o bastante?","esc":{"micro":"Corrigir os erros mais vistos.","meso":"Revisão das telas principais.","macro":"Refutar antes de publicar: revisão por falantes nativos e testes de leitura com o público local, com glossário."},"st":"mod","sub":"Remover textos traduzidos sem revisão.","ops":["U03","U30"],"c2":{"c":"C31","t":"Revisar tudo atrasa lançamentos.","mit":"Priorizar telas mais usadas."},"cf":"Sem intervenção, desconfiança.","lim":{"l":"L04","t":"Revisar todas as telas por falantes nativos tem custo e tempo."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se os erros forem raros.","conf":"média"},
{"id":89,"h":2,"sev":4,"t":"Instalação escrita para programadores","sym":"O guia pede para “configurar o DHCP” do roteador a um usuário leigo.","ten":"Quem escreveu sabe demais; quem lê não sabe o bastante.","sol":"Redistribuir a carga: o app detecta e configura a rede sozinho; guia visual simples para o que restar.","c":"C25","u":"U13","e":"meso","i":"I03","m":"Instalações concluídas sem ajuda","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["WC3.1","SH2","ISO4","BS4.2"],"dom":"casa","vul":"idosos","ag":"Ganha: quem instala. Perde: quem quer configurar à mão perde controle direto.","alt":"E se a instalação puder ser automática?","esc":{"micro":"Guia visual com fotos do próprio roteador em cada passo.","meso":"Redistribuir a carga: o app detecta e configura a rede sozinho; guia visual simples para o que restar.","macro":"Instalação por técnico."},"st":"sub","sub":"Remover etapas técnicas por automação.","ops":["U04","U32"],"c2":{"c":"C27","t":"Automação pode falhar em redes incomuns.","mit":"Manter um modo avançado para quem precisa configurar à mão."},"cf":"Sem intervenção, instalações falham.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I03"],"menos":["I07"]},"ref":"Estaria errada se o público for técnico.","conf":"alta"},
{"id":90,"h":2,"sev":2,"t":"Relatório por código de campanha","sym":"O relatório lista “cmp_4492” em vez do nome da campanha.","ten":"O dado é armazenado por código, mas é lido por pessoas.","sol":"Exibir nomes legíveis e deixar o código como detalhe secundário.","c":"C10","u":"U12","e":"meso","i":"I03","m":"Tempo de análise do relatório","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP5","GP3","BS7","GP7"],"dom":"trabalho","vul":"","ag":"Ganha: analistas. Perde: nada relevante.","alt":"E se os códigos forem usados para cruzar dados?","esc":{"micro":"Nomes legíveis na tabela.","meso":"Exibir nomes legíveis e deixar o código como detalhe secundário.","macro":"Padrão de nomes na criação das campanhas."},"st":"mod","sub":"Retirar os códigos da tela principal.","ops":["U16","U30"],"c2":{"c":"C35","t":"Nomes repetidos confundem.","mit":"Nome + data de início."},"cf":"Sem intervenção, a análise é lenta e sujeita a erros.","lim":{"l":"L06","t":"Depende de a equipe nomear as campanhas."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se os analistas usarem os códigos.","conf":"alta"},
{"id":91,"h":2,"sev":4,"t":"Termos médicos para pacientes","sym":"O formulário pergunta sobre “dispneia” e “cefaleia”.","ten":"A equipe médica pensa em termos clínicos; o paciente, em sintomas.","sol":"Linguagem comum (“falta de ar”, “dor de cabeça”) com o termo técnico entre parênteses.","c":"C25","u":"U04","e":"micro","i":"I06","m":"Respostas erradas em triagem","freq":3,"imp":3,"pers":2,"pf":"P01","hx":["WC3.1","GP5","SH2","BS8"],"dom":"saude","vul":"baixa escolaridade","ag":"Ganha: pacientes. Perde: a linguagem comum perde precisão clínica.","alt":"E se o termo técnico for necessário para a equipe médica?","esc":{"micro":"Linguagem comum (“falta de ar”, “dor de cabeça”) com o termo técnico entre parênteses.","meso":"Revisar todos os formulários de triagem.","macro":"Guia de linguagem simples da rede de saúde."},"st":"mod","sub":"Retirar termos técnicos da versão do paciente.","ops":["U09","U30"],"c2":{"c":"C34","t":"Simplificar perde precisão clínica.","mit":"Termo técnico entre parênteses."},"cf":"Sem intervenção, respostas erradas na triagem.","lim":{"l":"L06","t":"Protocolos clínicos exigem termos padronizados nos registros internos."},"ide":{"mais":["I06"],"menos":["I04"]},"ref":"Estaria errada se os pacientes entenderem os termos.","conf":"alta"},
{"id":92,"h":2,"sev":3,"t":"Horário ignora feriados locais","sym":"O site do posto de atendimento diz “aberto” num feriado municipal.","ten":"O horário é fixo no sistema, mas o calendário real varia por cidade.","sol":"Antecipar: calendário de feriados por localidade e aviso destacado de horário especial.","c":"C30","u":"U20","e":"macro","i":"I04","m":"Viagens perdidas até a loja","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["ISO2","MB2","GP2","TG1"],"dom":"publico","vul":"","ag":"Ganha: cidadãos. Perde: calendários desatualizados.","alt":"E se o horário mudar sem aviso por outros motivos (greve, falta de energia)?","esc":{"micro":"Aviso de horário especial.","meso":"Calendário de feriados por unidade.","macro":"Antecipar: calendário de feriados por localidade e aviso destacado de horário especial."},"st":"add","sub":"Retirar horários fixos codificados na página.","ops":["U21","U12"],"c2":{"c":"C36","t":"Calendários desatualizados.","mit":"Atualização automática."},"cf":"Sem intervenção, cidadãos se deslocam em vão.","lim":{"l":"L06","t":"Depende de cada unidade atualizar."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se os feriados forem raros.","conf":"alta"},
{"id":93,"h":2,"sev":4,"t":"Documento válido recusado","sym":"O banco não aceita a CNH digital nem o novo RG como identificação.","ten":"O sistema reconhece formatos antigos; o mundo já mudou.","sol":"Negociar a restrição: aceitar todos os documentos oficiais vigentes e revisar a regra quando surgirem novos.","c":"C36","u":"U29","e":"macro","i":"I06","m":"Cadastros recusados","freq":2,"imp":3,"pers":2,"pf":"P09","hx":["BS8","SH2","ISO1","BS4.1"],"dom":"financas","vul":"","ag":"Ganha: clientes. Perde: documentos novos podem não ser validáveis.","alt":"E se o documento não puder ser validado automaticamente?","esc":{"micro":"Aceitar os documentos no cadastro.","meso":"Validação automática dos formatos novos.","macro":"Negociar a restrição: aceitar todos os documentos oficiais vigentes e revisar a regra quando surgirem novos."},"st":"sub","sub":"A própria solução é subtrativa: remove a restrição.","ops":["U30","U36"],"c2":{"c":"C22","t":"Documentos novos podem não ser validáveis.","mit":"Validação manual por atendente quando a automática não reconhecer o documento."},"cf":"Sem intervenção, cadastros recusados.","lim":{"l":"L06","t":"Regulação bancária sobre identificação de clientes (conheça seu cliente)."},"ide":{"mais":["I06"],"menos":["I05"]},"ref":"Estaria errada se os documentos não forem oficiais.","conf":"alta"},
{"id":94,"h":2,"sev":2,"t":"Cronologia invertida sem aviso","sym":"O histórico mostra a mensagem mais nova embaixo numa tela e em cima em outra.","ten":"A ordem depende de quem programou, não de como se lê uma história.","sol":"Instituir uma regra única de ordem cronológica, dita no topo (“Mais recentes primeiro”), com opção de inverter.","c":"C27","u":"U30","e":"micro","i":"I03","m":"Leituras equivocadas do histórico","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["DN5","BS6","ISO3","SH1"],"dom":"comunicacao","vul":"","ag":"Ganha: quem acompanha conversas longas. Perde: quem preferia a ordem antiga numa das telas.","alt":"E se as duas ordens forem úteis em momentos diferentes (ler do início ou ver o mais recente)?","esc":{"micro":"Instituir uma regra única de ordem cronológica, dita no topo (“Mais recentes primeiro”), com opção de inverter.","meso":"Ordem única em todas as telas de histórico, com botão para inverter.","macro":"Regra de ordenação definida no design system para todas as listas temporais."},"st":"mod","sub":"Retirar a ordenação escolhida por cada tela; uma só regra para o produto.","ops":["U01","U14"],"c2":{"c":"C21","t":"Algumas pessoas querem ler do início, outras ver só o mais novo.","mit":"Botão de inverter lembrado por pessoa."},"cf":"Sem intervenção, as pessoas leem respostas antes das perguntas e interpretam errado.","lim":{"l":"L06","t":"Depende de as equipes adotarem a mesma regra."},"ide":{"mais":["I03","I04"],"menos":[]},"ref":"Estaria errada se ninguém se confundir em teste de leitura do histórico.","conf":"alta"},
{"id":95,"h":2,"sev":2,"t":"Menu com cobertura vencida","sym":"O portal de notícias mantém “Eleições 2022” na navegação principal.","ten":"Campanhas são temporárias, mas ninguém tirou o item do ar.","sol":"Selecionar: itens sazonais expiram sozinhos e a navegação é revisada periodicamente.","c":"C36","u":"U35","e":"meso","i":"I11","m":"Cliques em páginas vencidas","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["GP8","BS2.3","ISO1","TG17"],"dom":"comunicacao","vul":"","ag":"Ganha: leitores. Perde: nada relevante.","alt":"E se a cobertura for recorrente?","esc":{"micro":"Retirar o item vencido.","meso":"Selecionar: itens sazonais expiram sozinhos e a navegação é revisada periodicamente.","macro":"Processo editorial de revisão da navegação."},"st":"sub","sub":"A própria solução é subtrativa: remove o item vencido.","ops":["U21","U19"],"c2":{"c":"C34","t":"Remover itens pode quebrar links.","mit":"Redirecionar para o arquivo."},"cf":"Sem intervenção, cliques em páginas vencidas.","lim":{"l":"L06","t":"Retirar itens da navegação é decisão editorial, nem sempre técnica."},"ide":{"mais":["I11"],"menos":[]},"ref":"Estaria errada se a página ainda for útil.","conf":"alta"},
{"id":96,"h":2,"sev":1,"t":"Lista de países sem tradução","sym":"Na reserva de hotel, “Brazil” aparece entre “Bosnia” e “Brunei”, em inglês.","ten":"A lista veio pronta de uma biblioteca estrangeira.","sol":"Rehierarquizar a lista: nomes em português, o país mais provável no topo e busca por digitação.","c":"C29","u":"U11","e":"micro","i":"I03","m":"Tempo para escolher o país","freq":2,"imp":1,"pers":1,"pf":"P01","hx":["BS8","LX2","GP6","MB5"],"dom":"mobilidade","vul":"estrangeiros","ag":"Ganha: quem reserva. Perde: pré-selecionar o país pela localização erra para quem está viajando.","alt":"E se boa parte do público for estrangeiro? Então o país mais comum depende de quem acessa.","esc":{"micro":"Rehierarquizar a lista: nomes em português, o país mais provável no topo e busca por digitação.","meso":"Detectar o país pela conta ou pelo endereço de cobrança e pré-selecionar.","macro":"Lista de países traduzida e compartilhada entre os produtos da empresa."},"st":"mod","sub":"Retirar a lista em inglês vinda da biblioteca externa.","ops":["U02","U21"],"c2":{"c":"C29","t":"Pré-selecionar o país pela localização erra para quem está viajando.","mit":"Sugerir, sem impor, e permitir busca por digitação."},"cf":"Sem intervenção, o país é escolhido errado e a reserva gera cobrança em outra moeda.","lim":{"l":"L03","t":"A biblioteca externa pode não oferecer tradução."},"ide":{"mais":["I03"],"menos":["I05"]},"ref":"Estaria errada se o público do hotel for majoritariamente estrangeiro.","conf":"alta"},
{"id":97,"h":2,"sev":3,"t":"Extrato com linguagem contábil","sym":"O extrato mostra “débito” e “crédito”; o cliente não sabe se o dinheiro entrou ou saiu.","ten":"A contabilidade tem convenções; o cliente pensa em entrou e saiu.","sol":"“Entrou” e “Saiu” com sinais e cores, e o termo contábil nos detalhes.","c":"C35","u":"U04","e":"meso","i":"I03","m":"Contatos sobre extrato","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["GP5","GP4","BS7","WC3.1"],"dom":"financas","vul":"baixa escolaridade","ag":"Ganha: clientes que não conhecem contabilidade. Perde: nada relevante.","alt":"E se parte dos clientes for de contadores ou empresas? Então os dois vocabulários precisam existir.","esc":{"micro":"Rótulos “Entrou” e “Saiu” com sinal.","meso":"“Entrou” e “Saiu” com sinais e cores, e o termo contábil nos detalhes.","macro":"Visão técnica opcional para clientes empresariais."},"st":"mod","sub":"Retirar “débito” e “crédito” da visão padrão do extrato.","ops":["U16","U09"],"c2":{"c":"C35","t":"Contadores leem “Entrou/Saiu” como imprecisão.","mit":"Visão técnica ativável, com os termos contábeis."},"cf":"Sem intervenção, clientes acham que perderam dinheiro e ligam para o banco.","lim":{"l":"L06","t":"Normas de apresentação de extratos."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, os clientes entenderem débito e crédito sem erro.","conf":"alta"},
{"id":98,"h":2,"sev":3,"t":"Mapa de assentos irreal","sym":"O mapa de assentos do ônibus é uma grade genérica, sem janela, corredor nem saída.","ten":"O mapa é uma grade genérica, mas o espaço físico tem características.","sol":"Desenho fiel ao veículo ou sala, com janelas, corredores e saídas marcados.","c":"C02","u":"U16","e":"micro","i":"I04","m":"Trocas de assento","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["DN4","GP4","WC1.1","MB2"],"dom":"mobilidade","vul":"cegos (leitor de tela)","ag":"Ganha: passageiros, inclusive quem usa leitor de tela. Perde: o sistema precisa de dados por modelo de veículo.","alt":"E se o problema for a falta de informação sobre os assentos, e não o desenho?","esc":{"micro":"Desenho fiel ao veículo ou sala, com janelas, corredores e saídas marcados.","meso":"Mapa por modelo de ônibus, com janelas, corredor e saídas.","macro":"Padrão de dados de assentos compartilhado entre empresas de ônibus."},"st":"add","sub":"Retirar a grade genérica igual para todos os veículos.","ops":["U12","U30"],"c2":{"c":"C04","t":"Um mapa visual detalhado não serve a quem usa leitor de tela.","mit":"Descrição em texto de cada assento (“janela, fileira 3, perto da saída”)."},"cf":"Sem intervenção, passageiros escolhem assentos que não queriam e pedem troca.","lim":{"l":"L06","t":"Depende de as empresas enviarem o modelo do veículo."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se as trocas forem por outros motivos (viajar junto com alguém).","conf":"alta"},
{"id":99,"h":2,"sev":3,"t":"Números sem unidade de escala","sym":"O painel de previsão da IA mostra “12” sem dizer se são mil ou milhões.","ten":"A escala foi abreviada para caber, e perdeu o sentido.","sol":"Unidade explícita no eixo e no valor (“12 mil”, “R$ 12 mi”).","c":"C34","u":"U01","e":"micro","i":"I04","m":"Interpretações erradas","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["GP2","GP9","IA2","BS7"],"dom":"ia","vul":"","ag":"Ganha: quem decide com base na previsão. Perde: nada relevante.","alt":"E se o problema for o painel esconder também a incerteza da previsão?","esc":{"micro":"Unidade explícita no eixo e no valor (“12 mil”, “R$ 12 mi”).","meso":"Unidade e intervalo de confiança em todos os valores previstos.","macro":"Guia de visualização de dados da empresa."},"st":"add","sub":"Retirar abreviações ambíguas (“12”, “12k”) dos gráficos.","ops":["U30","U16"],"c2":{"c":"C17","t":"Unidades e intervalos em todo lugar poluem o painel.","mit":"Unidade no eixo; intervalo ao passar o cursor."},"cf":"Sem intervenção, decisões são tomadas com mil vezes o valor real.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I04","I09"],"menos":[]},"ref":"Estaria errada se todas as pessoas que usam o painel souberem a escala de cor.","conf":"média"},
{"id":100,"h":2,"sev":3,"t":"Devolução no vocabulário da loja","sym":"O fluxo pergunta primeiro “código da nota fiscal”, não “o que aconteceu?”.","ten":"O processo segue a burocracia interna, mas o cliente parte do problema.","sol":"Reorientar pelo problema do cliente: começar pelo motivo (“Veio com defeito”, “Não serviu”) e localizar o pedido sozinho.","c":"C32","u":"U06","e":"meso","i":"I06","m":"Devoluções concluídas online","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS8","ISO1","GP1","BS2.2"],"dom":"comercio","vul":"","ag":"Ganha: clientes. Perde: a loja recebe motivos menos padronizados.","alt":"E se o motivo decidir o caminho (troca, reembolso, assistência)? Então ele deve vir primeiro mesmo.","esc":{"micro":"Perguntar o motivo antes de tudo.","meso":"Reorientar pelo problema do cliente: começar pelo motivo (“Veio com defeito”, “Não serviu”) e localizar o pedido sozinho.","macro":"Devolução sem burocracia para defeitos evidentes."},"st":"sub","sub":"A própria solução é subtrativa: elimina a digitação do código da nota fiscal.","ops":["U02","U10"],"c2":{"c":"C26","t":"Motivos em texto livre dificultam a análise de qualidade.","mit":"Categorias de motivo com campo livre opcional."},"cf":"Sem intervenção, devoluções são abandonadas no meio e viram reclamação pública.","lim":{"l":"L06","t":"Regras do código de defesa do consumidor."},"ide":{"mais":["I06"],"menos":["I02"]},"ref":"Estaria errada se a maioria dos clientes tiver a nota fiscal à mão.","conf":"alta"}
);
